#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_repeat.h"
#include <torch/extension.h>
#include <vector>

namespace ascend_kernel {

constexpr int64_t MAX_DIMS = 8;
constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

struct RepeatTilingData {
    int64_t totalLength;
    int64_t formerNum;
    int64_t formerLength;
    int64_t tailNum;
    int64_t tailLength;
    int64_t tileLength;
    int64_t inputDim;
    int64_t inputShape[MAX_DIMS];
    int64_t repeats[MAX_DIMS];
    int64_t outputShape[MAX_DIMS];
    int64_t inputStrides[MAX_DIMS];
    int64_t outputStrides[MAX_DIMS];
};

at::Tensor repeat(const at::Tensor& self, at::IntArrayRef repeats) {
    // ---- Input validation ----
    TORCH_CHECK(self.device().type() == at::DeviceType::PrivateUse1,
                "repeat: input must be on NPU device");
    TORCH_CHECK(self.is_contiguous(),
                "repeat: input must be contiguous");
    TORCH_CHECK(self.scalar_type() == at::kFloat ||
                self.scalar_type() == at::kHalf ||
                self.scalar_type() == at::kBFloat16,
                "repeat: only float32, float16 and bfloat16 are supported");

    int64_t ndim = self.dim();
    TORCH_CHECK(static_cast<int64_t>(repeats.size()) == ndim,
                "repeat: repeats length must match input dimensions");

    // ---- Compute output shape ----
    std::vector<int64_t> outputShape(ndim);
    for (int64_t i = 0; i < ndim; ++i) {
        outputShape[i] = self.size(i) * repeats[i];
    }

    // ---- Create output tensor ----
    auto output = at::empty(outputShape, self.options());

    // ---- Compute total elements ----
    int64_t inputTotal = self.numel();
    int64_t outputTotal = output.numel();
    int64_t dtypeSize = self.element_size();

    // ---- Compute strides ----
    std::vector<int64_t> inputStrides(ndim);
    std::vector<int64_t> outputStrides(ndim);
    inputStrides[ndim - 1] = 1;
    outputStrides[ndim - 1] = 1;
    for (int64_t i = ndim - 2; i >= 0; --i) {
        inputStrides[i] = inputStrides[i + 1] * self.size(i + 1);
        outputStrides[i] = outputStrides[i + 1] * outputShape[i + 1];
    }

    // ---- Block-level tiling ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());

    // Align output total to cache line
    int64_t alignElements = CACHE_LINE_BYTE_LENGTH / dtypeSize;
    int64_t totalLengthAligned = ((outputTotal + alignElements - 1) / alignElements) * alignElements;

    int64_t formerNum = (totalLengthAligned / CACHE_LINE_BYTE_LENGTH) % coreNum;
    if (formerNum == 0) {
        formerNum = coreNum;
    }
    int64_t tailNum = coreNum - formerNum;

    int64_t formerLength = ((totalLengthAligned / coreNum + CACHE_LINE_BYTE_LENGTH - 1) / CACHE_LINE_BYTE_LENGTH) * CACHE_LINE_BYTE_LENGTH / dtypeSize;
    int64_t tailLength = (totalLengthAligned / coreNum / CACHE_LINE_BYTE_LENGTH) * CACHE_LINE_BYTE_LENGTH / dtypeSize;

    // ---- UB-level tiling ----
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    int64_t bufferCoefficient = 4;  // inQueueX * 2 + outQueueY * 2
    int64_t maxTileElements = static_cast<int64_t>(ubSize) / bufferCoefficient / dtypeSize;
    int64_t ubAlignElements = 32 / dtypeSize;
    int64_t tileLength = (maxTileElements / ubAlignElements) * ubAlignElements;
    if (tileLength < ubAlignElements) {
        tileLength = ubAlignElements;
    }

    // ---- Prepare tiling data ----
    RepeatTilingData tilingData;
    tilingData.totalLength = outputTotal;
    tilingData.formerNum = formerNum;
    tilingData.formerLength = formerLength;
    tilingData.tailNum = tailNum;
    tilingData.tailLength = tailLength;
    tilingData.tileLength = tileLength;
    tilingData.inputDim = ndim;

    for (int64_t i = 0; i < MAX_DIMS; ++i) {
        if (i < ndim) {
            tilingData.inputShape[i] = self.size(i);
            tilingData.repeats[i] = repeats[i];
            tilingData.outputShape[i] = outputShape[i];
            tilingData.inputStrides[i] = inputStrides[i];
            tilingData.outputStrides[i] = outputStrides[i];
        } else {
            tilingData.inputShape[i] = 1;
            tilingData.repeats[i] = 1;
            tilingData.outputShape[i] = 1;
            tilingData.inputStrides[i] = 1;
            tilingData.outputStrides[i] = 1;
        }
    }

    // ---- Allocate workspace for tiling data ----
    auto workspace = at::empty({static_cast<int64_t>(sizeof(RepeatTilingData))},
                               at::TensorOptions().dtype(at::kByte).device(self.device()));

    // Copy tiling data to device
    auto tilingDataHost = at::empty({static_cast<int64_t>(sizeof(RepeatTilingData))},
                                     at::TensorOptions().dtype(at::kByte).device(at::kCPU));
    memcpy(tilingDataHost.data_ptr(), &tilingData, sizeof(RepeatTilingData));
    auto tilingDataDevice = tilingDataHost.to(self.device());

    // ---- Launch kernel ----
    int64_t blockDim = coreNum;
    int64_t dtypeSizeVal = dtypeSize;
    GM_ADDR workspaceAddr = reinterpret_cast<GM_ADDR>(tilingDataDevice.data_ptr());

