#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t MAX_DIMS = 8;

struct RepeatTilingData {
    int64_t totalLength;        // output total elements
    int64_t formerNum;          // number of former cores
    int64_t formerLength;       // elements per former core
    int64_t tailNum;            // number of tail cores
    int64_t tailLength;         // elements per tail core
    int64_t tileLength;         // UB tile length (elements)
    int64_t inputDim;           // input dimensions
    int64_t inputShape[MAX_DIMS];
    int64_t repeats[MAX_DIMS];
    int64_t outputShape[MAX_DIMS];
    int64_t inputStrides[MAX_DIMS];
    int64_t outputStrides[MAX_DIMS];
};

template<typename T>
class RepeatKernel {
public:
    __aicore__ inline RepeatKernel() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tilingData) {
        xGm.SetGlobalBuffer((__gm__ T*)x);
        yGm.SetGlobalBuffer((__gm__ T*)y);

        // Load tiling data from GM
        __gm__ RepeatTilingData* tiling = (__gm__ RepeatTilingData*)tilingData;
        totalLength_ = tiling->totalLength;
        formerNum_ = tiling->formerNum;
        formerLength_ = tiling->formerLength;
        tailNum_ = tiling->tailNum;
        tailLength_ = tiling->tailLength;
        tileLength_ = tiling->tileLength;
        inputDim_ = tiling->inputDim;

        for (int64_t i = 0; i < MAX_DIMS; ++i) {
            inputShape_[i] = tiling->inputShape[i];
            repeats_[i] = tiling->repeats[i];
            outputShape_[i] = tiling->outputShape[i];
            inputStrides_[i] = tiling->inputStrides[i];
            outputStrides_[i] = tiling->outputStrides[i];
        }

        pipe.InitBuffer(inQueueX, 2, tileLength_ * sizeof(T));
        pipe.InitBuffer(outQueueY, 2, tileLength_ * sizeof(T));
    }

    __aicore__ inline void Process() {
        int64_t blockIdx = GetBlockIdx();
        int64_t blockLength = (blockIdx < formerNum_) ? formerLength_ : tailLength_;
        int64_t blockOffset = 0;
        if (blockIdx < formerNum_) {
            blockOffset = blockIdx * formerLength_;
        } else {
            blockOffset = formerNum_ * formerLength_ + (blockIdx - formerNum_) * tailLength_;
        }

        int64_t tileNum = (blockLength + tileLength_ - 1) / tileLength_;
        int64_t tailTileLength = blockLength - (tileNum - 1) * tileLength_;

        for (int64_t i = 0; i < tileNum; ++i) {
            int64_t curTileLength = (i == tileNum - 1) ? tailTileLength : tileLength_;
            CopyIn(blockOffset + i * tileLength_, curTileLength);
            CopyOut(blockOffset + i * tileLength_, curTileLength);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t offset, int64_t length) {
        LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();

        for (int64_t i = 0; i < length; ++i) {
            int64_t outIdx = offset + i;

            // Convert output linear index to multi-dimensional coordinates
            int64_t outCoords[MAX_DIMS];
            int64_t tmp = outIdx;
            for (int64_t d = inputDim_ - 1; d >= 0; --d) {
                outCoords[d] = tmp % outputShape_[d];
                tmp = tmp / outputShape_[d];
            }

            // Compute input coordinates (modulo)
            int64_t inCoords[MAX_DIMS];
            for (int64_t d = 0; d < inputDim_; ++d) {
                inCoords[d] = outCoords[d] % inputShape_[d];
            }

            // Convert input coordinates to linear index
            int64_t inIdx = 0;
            for (int64_t d = 0; d < inputDim_; ++d) {
                inIdx += inCoords[d] * inputStrides_[d];
            }

            xLocal.SetValue(i, xGm.GetValue(inIdx));
        }

        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void CopyOut(int64_t offset, int64_t length) {
        LocalTensor<T> xLocal = inQueueX.DeQue<T>();
        LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();

        // Copy from inQueue to outQueue
        for (int64_t i = 0; i < length; ++i) {
            yLocal.SetValue(i, xLocal.GetValue(i));
        }
        outQueueY.EnQue(yLocal);
        inQueueX.FreeTensor(xLocal);

        // Write back to GM
        LocalTensor<T> yLocalOut = outQueueY.DeQue<T>();

        DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint32_t>(length * sizeof(T));
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;
        DataCopyPad(yGm[offset], yLocalOut, copyParams);

        outQueueY.FreeTensor(yLocalOut);
    }

private:
    TPipe pipe;
    TQue<TPosition::VECIN, 2> inQueueX;
    TQue<TPosition::VECOUT, 2> outQueueY;
    GlobalTensor<T> xGm;
    GlobalTensor<T> yGm;

    int64_t totalLength_ = 0;
    int64_t formerNum_ = 0;
    int64_t formerLength_ = 0;
    int64_t tailNum_ = 0;
    int64_t tailLength_ = 0;
    int64_t tileLength_ = 0;
    int64_t inputDim_ = 0;
    int64_t inputShape_[MAX_DIMS];
    int64_t repeats_[MAX_DIMS];
    int64_t outputShape_[MAX_DIMS];
    int64_t inputStrides_[MAX_DIMS];
    int64_t outputStrides_[MAX_DIMS];
};

extern "C" __global__ __aicore__ void repeat(GM_ADDR x, GM_ADDR y, GM_ADDR tilingData, int64_t dtypeSize) {
    if (dtypeSize == 4) {
        RepeatKernel<float> op;
        op.Init(x, y, tilingData);
        op.Process();
    } else if (dtypeSize == 2) {
        RepeatKernel<half> op;
        op.Init(x, y, tilingData);
        op.Process();
    }
}
