13	using namespace AscendC;
14	
15	constexpr int64_t MAX_DIMS = 8;
16	
17	struct RepeatTilingData {
18	    int64_t totalLength;        // output total elements
19	    int64_t formerNum;          // number of former cores
20	    int64_t formerLength;       // elements per former core
21	    int64_t tailNum;            // number of tail cores
22	    int64_t tailLength;         // elements per tail core
23	    int64_t tileLength;         // UB tile length (elements)
24	    int64_t inputDim;           // input dimensions
25	    int64_t inputShape[MAX_DIMS];
26	    int64_t repeats[MAX_DIMS];
27	    int64_t outputShape[MAX_DIMS];
28	    int64_t inputStrides[MAX_DIMS];
29	    int64_t outputStrides[MAX_DIMS];
30	};
31	
32	template<typename T>
33	class RepeatKernel {
34	public:
35	    __aicore__ inline RepeatKernel() {}
36	
37	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tilingData) {
38	        xGm.SetGlobalBuffer((__gm__ T*)x);
39	        yGm.SetGlobalBuffer((__gm__ T*)y);
40	
41	        // Load tiling data from GM
42	        __gm__ RepeatTilingData* tiling = (__gm__ RepeatTilingData*)tilingData;
43	        totalLength_ = tiling->totalLength;
44	        formerNum_ = tiling->formerNum;
45	        formerLength_ = tiling->formerLength;
46	        tailNum_ = tiling->tailNum;
47	        tailLength_ = tiling->tailLength;
48	        tileLength_ = tiling->tileLength;
49	        inputDim_ = tiling->inputDim;
50	
51	        for (int64_t i = 0; i < MAX_DIMS; ++i) {
52	            inputShape_[i] = tiling->inputShape[i];
53	            repeats_[i] = tiling->repeats[i];
54	            outputShape_[i] = tiling->outputShape[i];
55	            inputStrides_[i] = tiling->inputStrides[i];
56	            outputStrides_[i] = tiling->outputStrides[i];
57	        }
58	
59	        pipe.InitBuffer(inQueueX, 2, tileLength_ * sizeof(T));
60	        pipe.InitBuffer(outQueueY, 2, tileLength_ * sizeof(T));
61	    }
62	
63	    __aicore__ inline void Process() {
64	        int64_t blockIdx = GetBlockIdx();
65	        int64_t blockLength = (blockIdx < formerNum_) ? formerLength_ : tailLength_;
66	        int64_t blockOffset = 0;
67	        if (blockIdx < formerNum_) {
68	            blockOffset = blockIdx * formerLength_;
69	        } else {
70	            blockOffset = formerNum_ * formerLength_ + (blockIdx - formerNum_) * tailLength_;
71	        }
72	
73	        int64_t tileNum = (blockLength + tileLength_ - 1) / tileLength_;
74	        int64_t tailTileLength = blockLength - (tileNum - 1) * tileLength_;
75	
76	        for (int64_t i = 0; i < tileNum; ++i) {
77	            int64_t curTileLength = (i == tileNum - 1) ? tailTileLength : tileLength_;
78	            CopyIn(blockOffset + i * tileLength_, curTileLength);
79	            CopyOut(blockOffset + i * tileLength_, curTileLength);
80	        }
81	    }
82	
83	private:
84	    __aicore__ inline void CopyIn(int64_t offset, int64_t length) {
85	        LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
86	
87	        for (int64_t i = 0; i < length; ++i) {
88	            int64_t outIdx = offset + i;
89	
90	            // Convert output linear index to multi-dimensional coordinates
91	            int64_t outCoords[MAX_DIMS];
92	            int64_t tmp = outIdx;
93	            for (int64_t d = inputDim_ - 1; d >= 0; --d) {
94	                outCoords[d] = tmp % outputShape_[d];
95	                tmp = tmp / outputShape_[d];
96	            }
97	
98	            // Compute input coordinates (modulo)
99	            int64_t inCoords[MAX_DIMS];
100	            for (int64_t d = 0; d < inputDim_; ++d) {
101	                inCoords[d] = outCoords[d] % inputShape_[d];
102	            }
103	
104	            // Convert input coordinates to linear index
105	            int64_t inIdx = 0;
106	            for (int64_t d = 0; d < inputDim_; ++d) {
107	                inIdx += inCoords[d] * inputStrides_[d];
108	            }
109	
110	            xLocal.SetValue(i, xGm.GetValue(inIdx));
111	        }
112	
113	        inQueueX.EnQue(xLocal);
114	    }
115	
116	    __aicore__ inline void CopyOut(int64_t offset, int64_t length) {
117	        LocalTensor<T> xLocal = inQueueX.DeQue<T>();
118	        LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
119	
120	        // Copy from inQueue to outQueue
121	        for (int64_t i = 0; i < length; ++i) {
122	            yLocal.SetValue(i, xLocal.GetValue(i));
123	        }
124	        outQueueY.EnQue(yLocal);
125	        inQueueX.FreeTensor(xLocal);
126	
127	        // Write back to GM
128	        LocalTensor<T> yLocalOut = outQueueY.DeQue<T>();
129	
130	        DataCopyExtParams copyParams;
131	        copyParams.blockCount = 1;
132	        copyParams.blockLen = static_cast<uint32_t>(length * sizeof(T));
133	        copyParams.srcStride = 0;
134	        copyParams.dstStride = 0;
135	        DataCopyPad(yGm[offset], yLocalOut, copyParams);
136	
137	        outQueueY.FreeTensor(yLocalOut);
138	    }
139	
140	private:
141	    TPipe pipe;
142	    TQue<TPosition::VECIN, 2> inQueueX;
143	    TQue<TPosition::VECOUT, 2> outQueueY;
144	    GlobalTensor<T> xGm;
145	    GlobalTensor<T> yGm;
146	
147	    int64_t totalLength_ = 0;
148	    int64_t formerNum_ = 0;
149	    int64_t formerLength_ = 0;
150	    int64_t tailNum_ = 0;
151	    int64_t tailLength_ = 0;
152	    int64_t tileLength_ = 0;
153	    int64_t inputDim_ = 0;
154	    int64_t inputShape_[MAX_DIMS];
155	    int64_t repeats_[MAX_DIMS];
156	    int64_t outputShape_[MAX_DIMS];
157	    int64_t inputStrides_[MAX_DIMS];
158	    int64_t outputStrides_[MAX_DIMS];
159	};
