161	extern "C" __global__ __aicore__ void repeat(GM_ADDR x, GM_ADDR y, GM_ADDR tilingData, int64_t dtypeSize) {
162	    if (dtypeSize == 4) {
163	        RepeatKernel<float> op;
164	        op.Init(x, y, tilingData);
165	        op.Process();
166	    } else if (dtypeSize == 2) {
167	        RepeatKernel<half> op;
168	        op.Init(x, y, tilingData);
169	        op.Process();
170	    }
171	}
