11	#pragma once
12	
13	#include "kernel_operator.h"
14	
15	constexpr int64_t MAX_DIMS = 8;
16	
17	struct RepeatTilingData {
18	    int32_t totalLength;
19	    int32_t formerNum;
20	    int32_t formerLength;
21	    int32_t tailNum;
22	    int32_t tailLength;
23	    int32_t tileLength;
24	    int32_t inputDim;
25	    int32_t inputShape[MAX_DIMS];
26	    int32_t repeats[MAX_DIMS];
27	    int32_t outputShape[MAX_DIMS];
28	    int32_t inputStrides[MAX_DIMS];
29	    int32_t outputStrides[MAX_DIMS];
30	};
31	
32	template <typename T>
33	class RepeatKernel {
34	public:
35	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tilingData, AscendC::TPipe *pipe) {
36	        // Copy tiling data from GM using int32_t copy
37	        auto *dst = reinterpret_cast<int32_t *>(&tiling_);
38	        auto *src = reinterpret_cast<__gm__ int32_t *>(tilingData);
39	        for (size_t i = 0; i < sizeof(RepeatTilingData) / sizeof(int32_t); ++i) {
40	            dst[i] = src[i];
41	        }
42	
43	        xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), tiling_.totalLength);
44	        yGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), tiling_.totalLength);
45	
46	        pipe_ = pipe;
47	        if ASCEND_IS_AIV {
48	            pipe_->InitBuffer(inQueueX_, 1, tiling_.tileLength * sizeof(T));
49	            pipe_->InitBuffer(outQueueY_, 1, tiling_.tileLength * sizeof(T));
50	        }
51	    }
52	
53	    __aicore__ inline void Process() {
54	        if ASCEND_IS_AIV {
55	            int64_t blockIdx = AscendC::GetBlockIdx();
56	            int64_t blockLength = (blockIdx < tiling_.formerNum) ? tiling_.formerLength : tiling_.tailLength;
57	            int64_t blockOffset = 0;
58	            if (blockIdx < tiling_.formerNum) {
59	                blockOffset = blockIdx * tiling_.formerLength;
60	            } else {
61	                blockOffset = tiling_.formerNum * tiling_.formerLength + (blockIdx - tiling_.formerNum) * tiling_.tailLength;
62	            }
63	
64	            int64_t tileNum = (blockLength + tiling_.tileLength - 1) / tiling_.tileLength;
65	            int64_t tailTileLength = blockLength - (tileNum - 1) * tiling_.tileLength;
66	
67	            for (int64_t i = 0; i < tileNum; ++i) {
68	                int64_t curTileLength = (i == tileNum - 1) ? tailTileLength : tiling_.tileLength;
69	                CopyIn(blockOffset + i * tiling_.tileLength, curTileLength);
70	                CopyOut(blockOffset + i * tiling_.tileLength, curTileLength);
71	            }
72	        }
73	    }
74	
75	private:
76	    __aicore__ inline void CopyIn(int64_t offset, int64_t length) {
77	        inQueueX_.AllocTensor<T>(xLocal_);
78	
79	        for (int64_t i = 0; i < length; ++i) {
80	            int64_t outIdx = offset + i;
81	
82	            // Convert output linear index to multi-dimensional coordinates
83	            int64_t outCoords[MAX_DIMS];
84	            int64_t tmp = outIdx;
85	            for (int64_t d = tiling_.inputDim - 1; d >= 0; --d) {
86	                outCoords[d] = tmp % tiling_.outputShape[d];
87	                tmp = tmp / tiling_.outputShape[d];
88	            }
89	
90	            // Compute input coordinates (modulo)
91	            int64_t inCoords[MAX_DIMS];
92	            for (int64_t d = 0; d < tiling_.inputDim; ++d) {
93	                inCoords[d] = outCoords[d] % tiling_.inputShape[d];
94	            }
95	
96	            // Convert input coordinates to linear index
97	            int64_t inIdx = 0;
98	            for (int64_t d = 0; d < tiling_.inputDim; ++d) {
99	                inIdx += inCoords[d] * tiling_.inputStrides[d];
100	            }
101	
102	            xLocal_.SetValue(i, xGm_.GetValue(inIdx));
103	        }
104	
105	        inQueueX_.EnQue(xLocal_);
106	    }
107	
108	    __aicore__ inline void CopyOut(int64_t offset, int64_t length) {
109	        inQueueX_.DeQue<T>(xLocal_);
110	        outQueueY_.AllocTensor<T>(yLocal_);
111	
112	        // Copy from inQueue to outQueue
113	        for (int64_t i = 0; i < length; ++i) {
114	            yLocal_.SetValue(i, xLocal_.GetValue(i));
115	        }
116	        outQueueY_.EnQue(yLocal_);
117	        inQueueX_.FreeTensor(xLocal_);
118	
119	        // Write back to GM
120	        outQueueY_.DeQue<T>(yLocal_);
121	
122	        // For small data, use element-wise write to avoid alignment issues
123	        int64_t bytes = length * sizeof(T);
124	        if (bytes < 32) {
125	            for (int64_t i = 0; i < length; ++i) {
126	                yGm_.SetValue(offset + i, yLocal_.GetValue(i));
127	            }
128	        } else {
129	            AscendC::DataCopyExtParams copyParams;
130	            copyParams.blockCount = 1;
131	            copyParams.blockLen = static_cast<uint32_t>(bytes);
132	            copyParams.srcStride = 0;
133	            copyParams.dstStride = 0;
134	            AscendC::DataCopyPad(yGm_[offset], yLocal_, copyParams);
135	        }
136	
137	        outQueueY_.FreeTensor(yLocal_);
138	    }
139	
140	private:
141	    RepeatTilingData tiling_{};
142	    AscendC::TPipe *pipe_{nullptr};
143	
144	    AscendC::GlobalTensor<T> xGm_;
145	    AscendC::GlobalTensor<T> yGm_;
146	
147	    AscendC::TQue<AscendC::TPosition::VECIN, 0> inQueueX_;
148	    AscendC::TQue<AscendC::TPosition::VECOUT, 0> outQueueY_;
149	
150	    AscendC::LocalTensor<T> xLocal_;
151	    AscendC::LocalTensor<T> yLocal_;
152	};
153	
154	extern "C" __global__ __aicore__ void repeat(GM_ADDR x, GM_ADDR y, GM_ADDR tilingData, int64_t dtypeSize) {
155	    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2);
156	    AscendC::TPipe pipe;
157	    if (dtypeSize == 4) {
158	        RepeatKernel<float> op;
159	        op.Init(x, y, tilingData, &pipe);
160	        op.Process();
161	    } else if (dtypeSize == 2) {
162	        RepeatKernel<half> op;
163	        op.Init(x, y, tilingData, &pipe);
164	        op.Process();
165	    }
166	}
