#pragma once

#include "kernel_operator.h"

constexpr int64_t MAX_DIMS = 8;

struct RepeatTilingData {
    int32_t totalLength;
    int32_t inputTotal;
    int32_t formerNum;
    int32_t formerLength;
    int32_t tailNum;
    int32_t tailLength;
    int32_t tileLength;
    int32_t inputDim;
    int32_t inputShape[MAX_DIMS];
    int32_t repeats[MAX_DIMS];
    int32_t outputShape[MAX_DIMS];
    int32_t inputStrides[MAX_DIMS];
    int32_t outputStrides[MAX_DIMS];
};

template <typename T>
class RepeatKernel {
public:
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tilingData, AscendC::TPipe *pipe) {
        // Copy tiling data from GM using int32_t copy
        auto *dst = reinterpret_cast<int32_t *>(&tiling_);
        auto *src = reinterpret_cast<__gm__ int32_t *>(tilingData);
        for (size_t i = 0; i < sizeof(RepeatTilingData) / sizeof(int32_t); ++i) {
            dst[i] = src[i];
        }

        xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), tiling_.inputTotal);
        yGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), tiling_.totalLength);

        pipe_ = pipe;
        if ASCEND_IS_AIV {
            // tileLength must be at least 32/sizeof(T) elements for alignment
            int32_t minTileLen = 32 / sizeof(T);
            int32_t tileLen = tiling_.tileLength;
            if (tileLen < minTileLen) {
                tileLen = minTileLen;
            }
            pipe_->InitBuffer(inQueueX_, 1, tileLen * sizeof(T));
            pipe_->InitBuffer(outQueueY_, 1, tileLen * sizeof(T));
        }
    }

    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            int64_t blockIdx = AscendC::GetBlockIdx();
            int64_t blockLength = (blockIdx < tiling_.formerNum) ? tiling_.formerLength : tiling_.tailLength;
            int64_t blockOffset = 0;
            if (blockIdx < tiling_.formerNum) {
                blockOffset = blockIdx * tiling_.formerLength;
            } else {
                blockOffset = tiling_.formerNum * tiling_.formerLength + (blockIdx - tiling_.formerNum) * tiling_.tailLength;
            }

            int64_t tileNum = (blockLength + tiling_.tileLength - 1) / tiling_.tileLength;
            int64_t tailTileLength = blockLength - (tileNum - 1) * tiling_.tileLength;

            for (int64_t i = 0; i < tileNum; ++i) {
                int64_t curTileLength = (i == tileNum - 1) ? tailTileLength : tiling_.tileLength;
                int64_t curOffset = blockOffset + i * tiling_.tileLength;
                if (curOffset >= tiling_.totalLength) {
                    break;
                }
                if (curOffset + curTileLength > tiling_.totalLength) {
                    curTileLength = tiling_.totalLength - curOffset;
                }
                CopyIn(curOffset, curTileLength);
                CopyOut(curOffset, curTileLength);
            }
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t offset, int64_t length) {
        inQueueX_.AllocTensor<T>(xLocal_);

        for (int64_t i = 0; i < length; ++i) {
            int64_t outIdx = offset + i;

            // Convert output linear index to multi-dimensional coordinates
            int64_t outCoords[MAX_DIMS];
            int64_t tmp = outIdx;
            for (int64_t d = tiling_.inputDim - 1; d >= 0; --d) {
                outCoords[d] = tmp % tiling_.outputShape[d];
                tmp = tmp / tiling_.outputShape[d];
            }

            // Compute input coordinates (modulo)
            int64_t inCoords[MAX_DIMS];
            for (int64_t d = 0; d < tiling_.inputDim; ++d) {
                inCoords[d] = outCoords[d] % tiling_.inputShape[d];
            }

            // Convert input coordinates to linear index
            int64_t inIdx = 0;
            for (int64_t d = 0; d < tiling_.inputDim; ++d) {
                inIdx += inCoords[d] * tiling_.inputStrides[d];
            }

            xLocal_.SetValue(i, xGm_.GetValue(inIdx));
        }

        inQueueX_.EnQue(xLocal_);
    }

    __aicore__ inline void CopyOut(int64_t offset, int64_t length) {
        inQueueX_.DeQue<T>(xLocal_);
        outQueueY_.AllocTensor<T>(yLocal_);

        // Copy from inQueue to outQueue
        for (int64_t i = 0; i < length; ++i) {
            yLocal_.SetValue(i, xLocal_.GetValue(i));
        }
        outQueueY_.EnQue(yLocal_);
        inQueueX_.FreeTensor(xLocal_);

        // Write back to GM
        outQueueY_.DeQue<T>(yLocal_);

        // Always use DataCopyPad - blockLen must be >= 32 bytes
        // For small data, we still copy the full aligned tile but only valid data matters
        int64_t bytes = length * sizeof(T);
        int64_t alignedBytes = ((bytes + 31) / 32) * 32;
        int64_t alignedLen = alignedBytes / sizeof(T);

        AscendC::DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint32_t>(alignedBytes);
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;
        AscendC::DataCopyPad(yGm_[offset], yLocal_, copyParams);

        outQueueY_.FreeTensor(yLocal_);
    }

private:
    RepeatTilingData tiling_{};
    AscendC::TPipe *pipe_{nullptr};

    AscendC::GlobalTensor<T> xGm_;
    AscendC::GlobalTensor<T> yGm_;

    AscendC::TQue<AscendC::TPosition::VECIN, 0> inQueueX_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 0> outQueueY_;

    AscendC::LocalTensor<T> xLocal_;
    AscendC::LocalTensor<T> yLocal_;
};

extern "C" __global__ __aicore__ void repeat(GM_ADDR x, GM_ADDR y, GM_ADDR tilingData, int64_t dtypeSize) {
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2);
    AscendC::TPipe pipe;
    if (dtypeSize == 4) {
        RepeatKernel<float> op;
        op.Init(x, y, tilingData, &pipe);
        op.Process();
    } else if (dtypeSize == 2) {
        RepeatKernel<half> op;
        op.Init(x, y, tilingData, &pipe);
        op.Process();
    }
}
