18	
19	constexpr int64_t MAX_DIMS = 8;
20	constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
21	constexpr int64_t DEFAULT_NUM_PHYSICAL_CORES = 40;
22	
23	struct RepeatTilingData {
24	    int32_t totalLength;
25	    int32_t inputTotal;
26	    int32_t formerNum;
27	    int32_t formerLength;
28	    int32_t tailNum;
29	    int32_t tailLength;
30	    int32_t tileLength;
31	    int32_t inputDim;
32	    int32_t inputShape[MAX_DIMS];
33	    int32_t repeats[MAX_DIMS];
34	    int32_t outputShape[MAX_DIMS];
35	    int32_t inputStrides[MAX_DIMS];
36	    int32_t outputStrides[MAX_DIMS];
37	};
38	
39	at::Tensor repeat(const at::Tensor& self, at::IntArrayRef repeats) {
40	    // ---- Input validation ----
41	    TORCH_CHECK(self.device().type() == at::DeviceType::PrivateUse1,
42	                "repeat: input must be on NPU device");
43	    TORCH_CHECK(self.is_contiguous(),
44	                "repeat: input must be contiguous");
45	    TORCH_CHECK(self.scalar_type() == at::kFloat ||
46	                self.scalar_type() == at::kHalf ||
47	                self.scalar_type() == at::kBFloat16,
48	                "repeat: only float32, float16 and bfloat16 are supported");
49	
50	    int64_t ndim = self.dim();
51	    TORCH_CHECK(static_cast<int64_t>(repeats.size()) == ndim,
52	                "repeat: repeats length must match input dimensions");
53	
54	    // ---- Compute output shape ----
55	    std::vector<int64_t> outputShape(ndim);
56	    for (int64_t i = 0; i < ndim; ++i) {
57	        outputShape[i] = self.size(i) * repeats[i];
58	    }
59	
60	    // ---- Create output tensor ----
61	    auto output = at::empty(outputShape, self.options());
62	
63	    // ---- Compute total elements ----
64	    int64_t inputTotal = self.numel();
65	    int64_t outputTotal = output.numel();
66	    int64_t dtypeSize = self.element_size();
67	
68	    // ---- Compute strides ----
69	    std::vector<int64_t> inputStrides(ndim);
70	    std::vector<int64_t> outputStrides(ndim);
71	    inputStrides[ndim - 1] = 1;
72	    outputStrides[ndim - 1] = 1;
73	    for (int64_t i = ndim - 2; i >= 0; --i) {
74	        inputStrides[i] = inputStrides[i + 1] * self.size(i + 1);
75	        outputStrides[i] = outputStrides[i + 1] * outputShape[i + 1];
76	    }
77	
78	    // ---- Block-level tiling (simplified) ----
79	    // Kernel will calculate per-unit distribution based on global unit count
80	    int64_t usedCoreNum = 1;  // Kernel uses GetBlockNum() * GetSubBlockNum() for actual distribution
81	
82	    // ---- UB-level tiling ----
83	    int64_t bufferCoefficient = 4;  // inQueueX * 2 + outQueueY * 2
84	    int64_t ubSize = 192 * 1024;  // 192KB default UB size
85	    int64_t maxTileElements = ubSize / bufferCoefficient / dtypeSize;
86	    int64_t ubAlignElements = 32 / dtypeSize;
87	    int64_t tileLength = (maxTileElements / ubAlignElements) * ubAlignElements;
88	    if (tileLength < ubAlignElements) {
89	        tileLength = ubAlignElements;
90	    }
91	
92	    // ---- Prepare tiling data ----
93	    RepeatTilingData tilingData;
94	    tilingData.totalLength = static_cast<int32_t>(outputTotal);
95	    tilingData.inputTotal = static_cast<int32_t>(inputTotal);
96	    tilingData.formerNum = static_cast<int32_t>(usedCoreNum);
97	    tilingData.formerLength = 0;  // Not used, kernel calculates itself
98	    tilingData.tailNum = 0;
99	    tilingData.tailLength = 0;
100	    tilingData.tileLength = 0;  // Not used in element-wise mode
101	    tilingData.inputDim = static_cast<int32_t>(ndim);
102	
103	    for (int64_t i = 0; i < MAX_DIMS; ++i) {
104	        if (i < ndim) {
105	            tilingData.inputShape[i] = static_cast<int32_t>(self.size(i));
106	            tilingData.repeats[i] = static_cast<int32_t>(repeats[i]);
107	            tilingData.outputShape[i] = static_cast<int32_t>(outputShape[i]);
108	            tilingData.inputStrides[i] = static_cast<int32_t>(inputStrides[i]);
109	            tilingData.outputStrides[i] = static_cast<int32_t>(outputStrides[i]);
110	        } else {
111	            tilingData.inputShape[i] = 1;
112	            tilingData.repeats[i] = 1;
113	            tilingData.outputShape[i] = 1;
114	            tilingData.inputStrides[i] = 1;
115	            tilingData.outputStrides[i] = 1;
116	        }
117	    }
118	
119	    // ---- Copy tiling data to NPU ----
120	    auto tilingCpu = at::empty({static_cast<int64_t>(sizeof(RepeatTilingData))},
121	                               at::device(at::kCPU).dtype(at::kByte));
122	    memcpy(tilingCpu.data_ptr(), &tilingData, sizeof(RepeatTilingData));
123	    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);
124	
125	    // ---- Launch kernel ----
126	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
127	    int64_t dtypeSizeVal = dtypeSize;
128	
129	    EXEC_KERNEL_CMD(repeat, blockDim, self, output, tilingNpu, dtypeSizeVal);
130	
131	    return output;
132	}
